#[path = "mixel_receiver_native.rs"]
mod receiver_native;
pub(crate) use receiver_native::{with_receiver_owner, with_receiver_owner_checked,
    with_receiver_owner_scope_checked, release_receiver_owner};
#[cfg(not(any(target_os = "android", target_os = "ios")))]
use crate::whiteboard;
#[cfg(target_os = "macos")]
use dispatch::Queue;
use enigo::{Enigo, Key, KeyboardControllable, MouseButton, MouseControllable};
use hbb_common::{
    get_time,
    message_proto::{pointer_device_event::Union::TouchEvent, touch_event::Union::ScaleUpdate},
