#[cfg(windows)]
#[tokio::main(flavor = "current_thread")]
async fn send_sas() -> ResultType<()> {
    if receiver_native::remote_scope() { bail!("scoped secure-attention service is unavailable"); }
    if crate::platform::is_physical_console_session().unwrap_or(true) {
        let mut stream = crate::ipc::connect(1000, crate::POSTFIX_SERVICE).await?;
        if !receiver_native::effect_admitted() { bail!("receiver generation was revoked before SAS"); }
        timeout(1000, stream.send(&crate::ipc::Data::SAS)).await??;
    } else {
        if !receiver_native::effect_admitted() { bail!("receiver generation was revoked before SAS"); }
        crate::platform::send_sas();
    };
    Ok(())
}

