pub async fn send_url_scheme(url: String) -> ResultType<()> {
    #[cfg(all(target_os = "macos", feature = "flutter"))]
    if crate::server::mixel_support_url::is_reserved_support_url(&url)
        && !crate::server::mixel_support_url::is_valid_support_url(&url) {
        bail!("Mixel support URL handoff rejected malformed intent");
    }
    #[cfg(all(target_os = "macos", feature = "flutter"))]
    if crate::server::mixel_support_url::is_valid_support_url(&url) {
        return match send_mixel_gui_intent_(url).await {
            crate::server::mixel_support_url::Handoff::Accepted => Ok(()),
            _ => bail!("Mixel support URL handoff was not acknowledged"),
        };
    }
    connect(1_000, "_url")
        .await?
        .send(&Data::UrlLink(url))
        .await?;
    Ok(())
}

#[cfg(all(target_os = "macos", feature = "flutter"))]
