#[cfg(all(target_os = "macos", feature = "flutter"))]
async fn send_mixel_gui_intent_(url: String) -> crate::server::mixel_support_url::Handoff {
    use crate::server::mixel_support_url::{Handoff, handoff_ack, is_valid_support_url};
    let support = is_valid_support_url(&url);
    if !support && !url.is_empty() { return Handoff::ExistingNeedsRetry; }
    let outcome = timeout(4_000, async {
        let mut conn = match connect_mixel_gui_peer().await {
            Ok(conn) => conn,
            Err(outcome) => return outcome,
        };
        if conn.send(&Data::UrlLink(url)).await.is_err() { return Handoff::ExistingNeedsRetry; }
        match conn.next_timeout(2_000).await {
            Ok(Some(Data::Config((name, value)))) => handoff_ack(&name, value.as_deref()),
            _ => Handoff::ExistingNeedsRetry,
        }
    }).await;
    outcome.unwrap_or(Handoff::ExistingNeedsRetry)
}

#[cfg(all(target_os = "macos", feature = "flutter"))]
async fn connect_mixel_gui_peer() -> Result<ConnectionTmpl<tokio::net::UnixStream>, crate::server::mixel_support_url::Handoff> {
    use std::os::unix::io::AsRawFd;
    use crate::server::mixel_support_url::{Handoff, transport_absent};
    let stream = match timeout(1_000, tokio::net::UnixStream::connect(Config::ipc_path("_url"))).await {
        Ok(Ok(stream)) => stream,
        Ok(Err(error)) if transport_absent(Some(error.kind())) => return Err(Handoff::NoReceiver),
        _ => return Err(Handoff::ExistingNeedsRetry),
    };
    if crate::server::mixel_gui_launch::peer::verify(stream.as_raw_fd()).is_err() { return Err(Handoff::ExistingNeedsRetry); }
    Ok(ConnectionTmpl::new(stream))
}

